1	// Meeting-room booking server: JSON API + static page, data kept in one JSON file.
2	// Node.js built-ins only. Run with `node server.mjs`.
3	import http from 'node:http';
4	import fs from 'node:fs';
5	import fsp from 'node:fs/promises';
6	import path from 'node:path';
7	import { fileURLToPath } from 'node:url';
8	
9	const HOST = '127.0.0.1';
10	const DEFAULT_PORT = 3000;
11	const MAX_PORT = 65535;
12	const DEFAULT_DATA_FILE = 'bookings.json';
13	const MAX_BODY_BYTES = 10000;
14	const MAX_TITLE_LENGTH = 80;
15	const ROOMS = Object.freeze(['Aurora', 'Borealis', 'Cosmos']);
16	const BOOKING_KEYS = Object.freeze(['id', 'room', 'title', 'date', 'start', 'end']);
17	const JSON_TYPE = 'application/json; charset=utf-8';
18	const PUBLIC_DIR = path.join(path.dirname(fileURLToPath(import.meta.url)), 'public');
19	const STATIC_FILES = Object.freeze({
20	  '/': { file: 'index.html', type: 'text/html; charset=utf-8' },
21	  '/app.js': { file: 'app.js', type: 'text/javascript; charset=utf-8' },
22	});
23	const BOOKING_PREFIX = '/api/bookings/';
24	
25	const MSG = Object.freeze({
26	  notFound: 'not found',
27	  methodNotAllowed: 'method not allowed',
28	  internal: 'internal error',
29	  bookingNotFound: 'booking not found',
30	  contentType: 'content type must be application/json',
31	  tooLarge: 'body too large',
32	  notObject: 'body must be a JSON object',
33	  room: `room must be one of ${ROOMS.join(', ')}`,
34	  title: `title must be 1 to ${MAX_TITLE_LENGTH} characters`,
35	  date: 'date must be a valid YYYY-MM-DD date',
36	  start: 'start must be HH:MM',
37	  end: 'end must be HH:MM',
38	  order: 'end must be after start',
39	});
40	
41	class HttpError extends Error {
42	  constructor(status, message) {
43	    super(message);
44	    this.status = status;
45	  }
46	}
47	
48	// ---------- validation ----------
49	
50	const DATE_RE = /^([0-9]{4})-([0-9]{2})-([0-9]{2})$/;
51	const TIME_RE = /^([01][0-9]|2[0-3]):[0-5][0-9]$/;
52	
53	function daysInMonth(year, month) {
54	  if (month === 2) return year % 4 === 0 ? 29 : 28;
55	  return [4, 6, 9, 11].includes(month) ? 30 : 31;
56	}
57	
58	function isValidDate(value) {
59	  if (typeof value !== 'string') return false;
60	  const match = DATE_RE.exec(value);
61	  if (!match) return false;
62	  const [year, month, day] = match.slice(1).map(Number);
63	  if (year < 2000 || year > 2099 || month < 1 || month > 12) return false;
64	  return day >= 1 && day <= daysInMonth(year, month);
65	}
66	
67	function isValidTime(value) {
68	  return typeof value === 'string' && TIME_RE.test(value);
69	}
70	
71	function isPlainObject(value) {
72	  return typeof value === 'object' && value !== null && !Array.isArray(value);
73	}
74	
75	function field(body, key) {
76	  return Object.hasOwn(body, key) ? body[key] : undefined;
77	}
78	
79	/** Applies booking rules 4-9; returns the normalised fields or throws HttpError 400. */
80	function validateFields(body) {
81	  const room = field(body, 'room');
82	  if (typeof room !== 'string' || !ROOMS.includes(room)) throw new HttpError(400, MSG.room);
83	  const rawTitle = field(body, 'title');
84	  const title = typeof rawTitle === 'string' ? rawTitle.trim() : null;
85	  if (title === null || title.length < 1 || title.length > MAX_TITLE_LENGTH) {
86	    throw new HttpError(400, MSG.title);
87	  }
88	  const date = field(body, 'date');
89	  if (!isValidDate(date)) throw new HttpError(400, MSG.date);
90	  const start = field(body, 'start');
91	  if (!isValidTime(start)) throw new HttpError(400, MSG.start);
92	  const end = field(body, 'end');
93	  if (!isValidTime(end)) throw new HttpError(400, MSG.end);
94	  if (!(end > start)) throw new HttpError(400, MSG.order);
95	  return { room, title, date, start, end };
96	}
97	
98	function findOverlap(bookings, candidate) {
99	  const clashes = bookings.filter((b) => b.room === candidate.room && b.date === candidate.date
100	    && b.start < candidate.end && candidate.start < b.end);
101	  return clashes.reduce((first, b) => (first === null || b.start < first.start ? b : first), null);
102	}
103	
104	function compareBookings(a, b) {
105	  if (a.date !== b.date) return a.date < b.date ? -1 : 1;
106	  if (a.start !== b.start) return a.start < b.start ? -1 : 1;
107	  return ROOMS.indexOf(a.room) - ROOMS.indexOf(b.room);
108	}
109	
110	// ---------- data file ----------
111	
112	const STATE_KEYS = Object.freeze(['nextId', 'bookings']);
113	
114	function hasExactKeys(obj, expected) {
115	  const keys = Object.keys(obj);
116	  return keys.length === expected.length && expected.every((k) => keys.includes(k));
117	}
118	
119	function isStoredBooking(b, nextId) {
120	  if (!isPlainObject(b) || !hasExactKeys(b, BOOKING_KEYS)) return false;
121	  if (!Number.isSafeInteger(b.id) || b.id < 1 || b.id >= nextId) return false;
122	  try {
123	    const fields = validateFields(b);
124	    return fields.title === b.title;
125	  } catch (err) {
126	    if (err instanceof HttpError) return false;
127	    throw err;
128	  }
129	}
130	
131	/** Returns a frozen state or null when the content is not in this server's layout. */
132	function parseState(text) {
133	  let data;
134	  try {
135	    data = JSON.parse(text);
136	  } catch {
137	    return null; // invalid JSON is reported by the caller as an unreadable data file
138	  }
139	  if (!isPlainObject(data) || !hasExactKeys(data, STATE_KEYS)) return null;
140	  if (!Number.isSafeInteger(data.nextId) || data.nextId < 1) return null;
141	  if (!Array.isArray(data.bookings)) return null;
142	  if (!data.bookings.every((b) => isStoredBooking(b, data.nextId))) return null;
143	  if (new Set(data.bookings.map((b) => b.id)).size !== data.bookings.length) return null;
144	  const clash = data.bookings.some((b, i) => findOverlap(data.bookings.slice(0, i), b) !== null);
145	  if (clash) return null;
146	  return freezeState({ nextId: data.nextId, bookings: data.bookings });
147	}
148	
149	function freezeState({ nextId, bookings }) {
150	  return Object.freeze({ nextId, bookings: Object.freeze(bookings.map((b) => Object.freeze({ ...b }))) });
151	}
152	
153	/** Reads the data file once; returns the state or null when it cannot be used. */
154	function loadState(filePath) {
155	  let text;
156	  try {
157	    text = fs.readFileSync(filePath, 'utf8');
158	  } catch (err) {
159	    if (err.code === 'ENOENT') return freezeState({ nextId: 1, bookings: [] });
160	    return null;
161	  }
162	  return parseState(text);
163	}
164	
165	let tempCounter = 0;
166	
167	async function saveState(filePath, state) {
168	  tempCounter += 1;
169	  const tempPath = `${filePath}.${process.pid}.${tempCounter}.tmp`;
170	  const json = JSON.stringify({ nextId: state.nextId, bookings: state.bookings });
171	  try {
172	    await fsp.writeFile(tempPath, json, { flag: 'wx' });
173	    await fsp.rename(tempPath, filePath);
174	  } catch (err) {
175	    await fsp.rm(tempPath, { force: true }).catch((rmErr) => logError('temp cleanup failed', rmErr));
176	    throw err;
177	  }
178	}
179	
180	// ---------- HTTP plumbing ----------
181	
182	function logError(context, err) {
183	  process.stderr.write(`${context}: ${err && err.message ? err.message : String(err)}\n`);
184	}
185	
186	function readBody(req) {
187	  return new Promise((resolve, reject) => {
188	    const chunks = [];
189	    let size = 0;
190	    req.on('data', (chunk) => {
191	      size += chunk.length;
192	      if (size <= MAX_BODY_BYTES) chunks.push(chunk);
193	    });
194	    req.on('end', () => resolve({ size, buffer: size <= MAX_BODY_BYTES ? Buffer.concat(chunks) : null }));
195	    req.on('error', reject);
196	  });
197	}
198	
199	function send(res, status, body, type = JSON_TYPE) {
200	  if (body === undefined) {
201	    res.writeHead(status);
202	    res.end();
203	    return;
204	  }
205	  const payload = typeof body === 'string' || Buffer.isBuffer(body) ? body : JSON.stringify(body);
206	  res.writeHead(status, { 'Content-Type': type, 'Content-Length': Buffer.byteLength(payload) });
207	  res.end(payload);
208	}
209	
210	function sendError(res, status, message) {
211	  send(res, status, { error: message });
212	}
213	
214	function mediaType(header) {
215	  if (typeof header !== 'string') return null;
216	  return header.split(';')[0].replace(/^[ \t]+|[ \t]+$/g, '').toLowerCase();
217	}
218	
219	function parseJsonObject(buffer) {
220	  try {
221	    const value = JSON.parse(buffer.toString('utf8'));
222	    return isPlainObject(value) ? value : null;
223	  } catch {
224	    return null; // any parse failure means the body is not a JSON object (rule 3)
225	  }
226	}
227	
228	// ---------- app ----------
229	
230	function createApp(dataPath, initialState) {
231	  let state = initialState;
232	  let queue = Promise.resolve();
233	
234	  /** Runs mutations one at a time so concurrent requests behave sequentially. */
235	  function serialize(task) {
236	    const run = queue.then(task);
237	    queue = run.catch(() => undefined); // the failure is handled by the caller awaiting `run`
238	    return run;
239	  }
240	
241	  async function commit(nextState) {
242	    const frozen = freezeState(nextState);
243	    await saveState(dataPath, frozen);
244	    state = frozen;
245	  }
246	
247	  function listBookings(query) {
248	    const params = new URLSearchParams(query);
249	    let bookings = [...state.bookings];
250	    if (params.has('date')) {
251	      const date = params.get('date');
252	      if (!isValidDate(date)) throw new HttpError(400, MSG.date);
253	      bookings = bookings.filter((b) => b.date === date);
254	    }
255	    return { bookings: bookings.sort(compareBookings) };
256	  }
257	
258	  function createBooking(req, body) {
259	    if (mediaType(req.headers['content-type']) !== 'application/json') {
260	      throw new HttpError(415, MSG.contentType);
261	    }
262	    if (body.size > MAX_BODY_BYTES) throw new HttpError(413, MSG.tooLarge);
263	    const parsed = parseJsonObject(body.buffer);
264	    if (parsed === null) throw new HttpError(400, MSG.notObject);
265	    const fields = validateFields(parsed);
266	    return serialize(async () => {
267	      const clash = findOverlap(state.bookings, fields);
268	      if (clash) throw new HttpError(409, `room is already booked from ${clash.start} to ${clash.end}`);
269	      const booking = { id: state.nextId, ...fields };
270	      await commit({ nextId: state.nextId + 1, bookings: [...state.bookings, booking] });
271	      return booking;
272	    });
273	  }
274	
275	  function deleteBooking(idText) {
276	    return serialize(async () => {
277	      const id = /^[1-9][0-9]*$/.test(idText) ? Number(idText) : NaN;
278	      if (!state.bookings.some((b) => b.id === id)) throw new HttpError(404, MSG.bookingNotFound);
279	      await commit({ nextId: state.nextId, bookings: state.bookings.filter((b) => b.id !== id) });
280	    });
281	  }
282	
283	  async function serveStatic(res, entry) {
284	    const content = await fsp.readFile(path.join(PUBLIC_DIR, entry.file));
285	    send(res, 200, content, entry.type);
286	  }
287	
288	  /** Resolves the route for a raw path; returns null when the path is unknown. */
289	  function route(pathName, query, req, body, res) {
290	    if (pathName === '/api/rooms') return { GET: () => send(res, 200, { rooms: ROOMS }) };
291	    if (pathName === '/api/bookings') {
292	      return {
293	        GET: () => send(res, 200, listBookings(query)),
294	        POST: async () => send(res, 201, await createBooking(req, body)),
295	      };
296	    }
297	    if (pathName.startsWith(BOOKING_PREFIX)) {
298	      const id = pathName.slice(BOOKING_PREFIX.length);
299	      if (id === '' || id.includes('/')) return null;
300	      return { DELETE: async () => { await deleteBooking(id); send(res, 204); } };
301	    }
302	    if (Object.hasOwn(STATIC_FILES, pathName)) {
303	      return { GET: () => serveStatic(res, STATIC_FILES[pathName]) };
304	    }
305	    return null;
306	  }
307	
308	  async function handle(req, res) {
309	    const body = await readBody(req);
310	    const target = req.url;
311	    const queryStart = target.indexOf('?');
312	    const pathName = queryStart === -1 ? target : target.slice(0, queryStart);
313	    const query = queryStart === -1 ? '' : target.slice(queryStart + 1);
314	    const handlers = route(pathName, query, req, body, res);
315	    if (handlers === null) return sendError(res, 404, MSG.notFound);
316	    if (!Object.hasOwn(handlers, req.method)) return sendError(res, 405, MSG.methodNotAllowed);
317	    return handlers[req.method]();
318	  }
319	
320	  return async function onRequest(req, res) {
321	    try {
322	      await handle(req, res);
323	    } catch (err) {
324	      if (err instanceof HttpError) {
325	        sendError(res, err.status, err.message);
326	        return;
327	      }
328	      logError('request failed', err);
329	      if (!res.headersSent) sendError(res, 500, MSG.internal);
330	      else res.destroy();
331	    }
332	  };
333	}
334	
335	// ---------- startup ----------
336	
337	function parsePort(raw) {
338	  if (raw === undefined || raw === '') return DEFAULT_PORT;
339	  if (!/^[0-9]+$/.test(raw)) return null;
340	  const port = Number(raw);
341	  return port <= MAX_PORT ? port : null;
342	}
343	
344	/** Writes one stderr line and lets the process exit with code 1 (nothing else keeps it alive). */
345	function failStartup(message) {
346	  process.stderr.write(`${message}\n`);
347	  process.exitCode = 1;
348	}
349	
350	function main() {
351	  const port = parsePort(process.env.PORT);
352	  if (port === null) return failStartup(`invalid PORT: ${JSON.stringify(process.env.PORT)}`);
353	  const dataName = process.env.DATA_FILE || DEFAULT_DATA_FILE;
354	  const dataPath = path.resolve(process.cwd(), dataName);
355	  const state = loadState(dataPath);
356	  if (state === null) return failStartup(`cannot read data file ${dataName}`);
357	  const server = http.createServer(createApp(dataPath, state));
358	  server.on('error', (err) => failStartup(`cannot listen on ${HOST}:${port}: ${err.code || err.message}`));
359	  server.listen(port, HOST, () => {
360	    process.stdout.write(`listening on http://${HOST}:${server.address().port}\n`);
361	  });
362	}
363	
364	main();
