1	'use strict';
2	
3	(function setupBookingPage() {
4	  const NO_REPLY = 'Could not reach the server.';
5	  const FALLBACK_ERROR = 'Request failed.';
6	  const SUCCESS_STATUS = { GET: 200, POST: 201, DELETE: 204 };
7	
8	  const form = document.getElementById('booking-form');
9	  const roomSelect = document.getElementById('room');
10	  const titleInput = document.getElementById('title');
11	  const dateInput = document.getElementById('date');
12	  const startInput = document.getElementById('start');
13	  const endInput = document.getElementById('end');
14	  const bookButton = document.getElementById('book');
15	  const filterDate = document.getElementById('filter-date');
16	  const showAllButton = document.getElementById('show-all');
17	  const bookingList = document.getElementById('booking-list');
18	  const errorBox = document.getElementById('error');
19	
20	  let listGeneration = 0;
21	
22	  // Resolves to { ok, status, body } when a reply arrived, or null when there was none.
23	  // A non-204 reply whose body is not JSON counts as no reply.
24	  async function request(method, url, payload) {
25	    const options = payload === undefined
26	      ? { method }
27	      : { method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) };
28	    try {
29	      const reply = await fetch(url, options);
30	      const body = reply.status === 204 ? undefined : await reply.json();
31	      return { ok: reply.status === SUCCESS_STATUS[method], status: reply.status, body };
32	    } catch {
33	      // Network failure or unreadable body: the caller shows the no-reply message.
34	      return null;
35	    }
36	  }
37	
38	  function isPlainObject(value) {
39	    return value !== null && typeof value === 'object' && !Array.isArray(value);
40	  }
41	
42	  function errorMessage(body) {
43	    return isPlainObject(body) && typeof body.error === 'string' ? body.error : FALLBACK_ERROR;
44	  }
45	
46	  // The array under `key` in a success body, or null when the body has an unexpected shape.
47	  function listField(body, key) {
48	    return isPlainObject(body) && Array.isArray(body[key]) ? body[key] : null;
49	  }
50	
51	  function showError(text) {
52	    errorBox.textContent = text;
53	  }
54	
55	  function showOutcomeError(result) {
56	    showError(result === null ? NO_REPLY : errorMessage(result.body));
57	  }
58	
59	  async function loadRooms() {
60	    const result = await request('GET', '/api/rooms');
61	    if (result === null || !result.ok) {
62	      showOutcomeError(result);
63	      return;
64	    }
65	    const rooms = listField(result.body, 'rooms');
66	    if (rooms === null) {
67	      showError(FALLBACK_ERROR);
68	      return;
69	    }
70	    const options = rooms.map((name) => {
71	      const option = document.createElement('option');
72	      option.value = name;
73	      option.textContent = name;
74	      return option;
75	    });
76	    roomSelect.replaceChildren(...options);
77	  }
78	
79	  function bookingItem(booking) {
80	    const item = document.createElement('li');
81	    const cancel = document.createElement('button');
82	    cancel.type = 'button';
83	    cancel.textContent = 'Cancel';
84	    cancel.addEventListener('click', () => cancelBooking(booking.id, cancel));
85	    const text = `${booking.date} ${booking.start}-${booking.end} ${booking.room}: ${booking.title}`;
86	    item.append(text, cancel);
87	    return item;
88	  }
89	
90	  function emptyItem() {
91	    const item = document.createElement('li');
92	    item.append('No bookings.');
93	    return item;
94	  }
95	
96	  async function loadList() {
97	    listGeneration += 1;
98	    const generation = listGeneration;
99	    const filter = filterDate.value;
100	    const url = filter === '' ? '/api/bookings' : `/api/bookings?date=${filter}`;
101	    const result = await request('GET', url);
102	    if (generation !== listGeneration) {
103	      return;
104	    }
105	    if (result === null || !result.ok) {
106	      showOutcomeError(result);
107	      return;
108	    }
109	    const bookings = listField(result.body, 'bookings');
110	    if (bookings === null || !bookings.every(isPlainObject)) {
111	      showError(FALLBACK_ERROR);
112	      return;
113	    }
114	    const items = bookings.length === 0 ? [emptyItem()] : bookings.map(bookingItem);
115	    bookingList.replaceChildren(...items);
116	  }
117	
118	  async function cancelBooking(id, button) {
119	    button.disabled = true;
120	    const result = await request('DELETE', `/api/bookings/${id}`);
121	    button.disabled = false;
122	    if (result === null) {
123	      showError(NO_REPLY);
124	      return;
125	    }
126	    showError(result.ok ? '' : errorMessage(result.body));
127	    loadList();
128	  }
129	
130	  async function submitBooking(event) {
131	    event.preventDefault();
132	    if (bookButton.disabled) {
133	      return;
134	    }
135	    bookButton.disabled = true;
136	    const payload = {
137	      room: roomSelect.value,
138	      title: titleInput.value,
139	      date: dateInput.value,
140	      start: startInput.value,
141	      end: endInput.value,
142	    };
143	    const result = await request('POST', '/api/bookings', payload);
144	    bookButton.disabled = false;
145	    if (result === null || !result.ok) {
146	      showOutcomeError(result);
147	      return;
148	    }
149	    titleInput.value = '';
150	    showError('');
151	    loadList();
152	  }
153	
154	  function showAll() {
155	    filterDate.value = '';
156	    loadList();
157	  }
158	
159	  form.addEventListener('submit', submitBooking);
160	  filterDate.addEventListener('change', () => loadList());
161	  showAllButton.addEventListener('click', showAll);
162	
163	  loadRooms();
164	  loadList();
165	})();
