1	// Hostile input: aborted uploads, malformed request targets and prototype-pollution bodies must
2	// neither crash nor hang the server, and stdout must stay the single listening line.
3	import { test } from 'node:test';
4	import assert from 'node:assert/strict';
5	import net from 'node:net';
6	import fs from 'node:fs';
7	import path from 'node:path';
8	import {
9	  boot, startServer, stopServer, makeTmp, request, post, rawRequest, valid, assertError,
10	} from './helpers/server-harness.mjs';
11	
12	const ROOMS_BODY = { rooms: ['Aurora', 'Borealis', 'Cosmos'] };
13	
14	/** Opens a POST, sends part of the declared body, then destroys the socket. */
15	function abortMidBody(port, declared, sent) {
16	  return new Promise((resolve) => {
17	    const socket = net.connect(port, '127.0.0.1', () => {
18	      socket.write(`POST /api/bookings HTTP/1.1\r\nHost: x\r\nContent-Type: application/json\r\n`
19	        + `Content-Length: ${declared}\r\n\r\n${'{'.repeat(sent)}`, () => {
20	        socket.destroy();
21	        resolve();
22	      });
23	    });
24	    socket.on('error', () => resolve()); // the abort itself is the point of this helper
25	  });
26	}
27	
28	async function assertAlive(srv, label) {
29	  const res = await request(srv.port, 'GET', '/api/rooms');
30	  assert.equal(res.status, 200, `${label}: still answering`);
31	  assert.deepEqual(res.json, ROOMS_BODY, `${label}: rooms body`);
32	  assert.equal(srv.out(), `listening on http://127.0.0.1:${srv.port}\n`, `${label}: stdout`);
33	}
34	
35	test('aborted uploads neither crash nor block later requests', async (t) => {
36	  const srv = await boot(t);
37	  await Promise.all(Array.from({ length: 20 }, (_, i) => abortMidBody(srv.port, 5000 + i, 100 + i)));
38	  await Promise.all(Array.from({ length: 5 }, () => abortMidBody(srv.port, 20000, 15000)));
39	  await assertAlive(srv, 'after aborts');
40	  const created = await post(srv.port, valid());
41	  assert.equal(created.status, 201, 'POST after aborts');
42	  assert.equal(created.json.id, 1, 'aborted uploads consume no id');
43	});
